  first: '#C9D1D6',
  last: '#4C5965',
  negative: '#D62222',
  positive: '#009900',
};

export const CORES_COMPOSITION_WATERFALL_COLORS = {
  first: '#4C5965',
  last: '#4C5965',
  retained: '#4C5965',
  positive: '#C9D1D6',
  negative: '#C9D1D6',
};

